Drupal.behaviors.addParagraphModalId = {
  attach: function attach(context, settings) {
    var $ = jQuery;
    $('.paragraph--type--modal', context).once().each(function () {
      var modalId = $(this).attr('id');

      if (modalId) {
        $(this).append('<div><strong>Modal ID:</strong> ' + modalId + '</div>');
      }
    });
  }
};

